TypeHintSource: TypeAlias = "Literal[\"graph\", \"hint\", \"none\"] | str"


class TypeHints(TypedDict):
    """Provisional classification of an address the knowledge graph has not reached yet.

    Hints are positive and non-exclusive: a freshly deployed token carries both
    `contract`
    and `fungible_token`. They are a list, never a set of booleans — a `false` here
    would
    read as a negative fact that was never established.
    """

    evidenceBlock: NotRequired[int | None]
    """Newest block among the evidence behind the hints. Present only with `source: hint`.

    """

    hints: NotRequired[list[str]]
    """Hints observed for the address. Vocabulary: `contract`, `fungible_token`,
    `nft_collection`, `multi_token_collection`, `eoa`. Present only with `source: hint`.
    """

    source: TypeHintSource


