class ValidatorWithdrawals(TypedDict):
    """One page of a validator's withdrawals, newest first, inside a block window.

    Every request is answered over a window of at most 216 000 blocks (about 30 days):
    the
    newest window by default, or the one asked for with `fromBlock` / `toBlock`. The
    window is echoed in `window`; to read further back, ask again with
    `toBlock = window.fromBlock - 1`. `nextCursor` pages inside the window only.
    """

    chainId: int
    """Chain id the facts are about. `1` is Ethereum mainnet."""

    nextCursor: NotRequired[str | None]
    """Cursor of the next page inside the window. Absent on the window's last page."""

    validatorIndex: int
    """The validator's index in the consensus registry."""

    window: WithdrawalWindow
    """The window this page was answered over."""

    withdrawals: list[ValidatorWithdrawal]
    """Newest first. Empty when the validator was paid nothing in the window — which is
    also what an index the chain does not know yet answers.
    """


class ValidatorWithdrawalsResponse(TypedDict):
    """Response of the validator-withdrawals method."""

    data: ValidatorWithdrawals

    meta: PublicMeta


class WithdrawalWindow(TypedDict):
    """The inclusive block window a page was answered over."""

    fromBlock: int
    """Lowest block of the window, inclusive."""

    toBlock: int
    """Highest block of the window, inclusive."""


